from itertools import permutations, product

countries = ("South Korea", "France", "Britain", "Germany")
languages = frozenset(("Korean", "French", "English", "German"))

options = {
    "A": ("Britain", "Germany", "South Korea", "France"),
    "B": ("France", "Britain", "Germany", "South Korea"),
    "C": ("Germany", "Britain", "France", "South Korea"),
    "D": ("Germany", "Britain", "South Korea", "France"),
}
submitted = "D"

# Include native languages and every explicitly stated foreign language.
# Do not assume that unstated foreign languages are impossible: enumerate them.
base = {
    "South Korea": frozenset(("Korean",)),
    "France": frozenset(("French", "German")),
    "Britain": frozenset(("English", "Korean")),
    "Germany": languages,
}

def supersets(required):
    optional = sorted(languages - required)
    return [
        required | frozenset(
            language for language, included in zip(optional, bits) if included
        )
        for bits in product((False, True), repeat=len(optional))
    ]

def violations(order, spoken):
    positions = {country: i for i, country in enumerate(order)}
    communicating_neighbors = {}
    for country, i in positions.items():
        neighbors = [
            order[j] for j in (i - 1, i + 1) if 0 <= j < len(order)
        ]
        communicating_neighbors[country] = [
            neighbor for neighbor in neighbors
            if spoken[country] & spoken[neighbor]
        ]

    errors = []
    if positions["South Korea"] <= positions["Germany"]:
        errors.append("Korean room number is not larger than German room number")
    for country in ("South Korea", "France"):
        if communicating_neighbors[country]:
            errors.append(
                f"{country} can communicate with adjacent "
                + ", ".join(communicating_neighbors[country])
            )
    if len(communicating_neighbors["Britain"]) != 1:
        errors.append(
            "Britain has "
            f"{len(communicating_neighbors['Britain'])} communicating neighbors, "
            "not exactly one"
        )
    return errors

models = [
    {
        "South Korea": base["South Korea"],
        "France": french,
        "Britain": british,
        "Germany": base["Germany"],
    }
    for french, british in product(
        supersets(base["France"]), supersets(base["Britain"])
    )
]

valid_orders = set()
witnesses = {}
for order in permutations(countries):
    for spoken in models:
        if not violations(order, spoken):
            valid_orders.add(order)
            witnesses.setdefault(order, spoken)

print("Exhaustively checked", len(models) * 24, "order/language assignments.")
print("Communication means sharing at least one spoken language.")
for label, order in options.items():
    print(f"{label}: {', '.join(order)} -> "
          f"{'VALID' if order in valid_orders else 'INVALID'}")

print("All feasible room orders:")
for order in sorted(valid_orders):
    print("  " + ", ".join(order))

print("Submitted option:", submitted)
for error in violations(options[submitted], base):
    print("Violation:", error)

expected = [label for label, order in options.items() if order in valid_orders]
if len(valid_orders) == 1 and len(expected) == 1:
    print("Expected answer:", expected[0])
    print("CHECK PASS" if submitted == expected[0] else "CHECK FAIL")
elif options[submitted] not in valid_orders:
    print("CHECK FAIL")
else:
    print("UNSUPPORTED: the constraints do not determine a unique answer.")
    print("CHECK UNKNOWN")
